using System;using System.Linq;using LighthouseKeepers.Core;using LighthouseKeepers.Lobby;using UnityEngine;using NUnit.Framework;
namespace LighthouseKeepers.Net.Tests {
 public sealed class RadioRelayTests {
  static Type T(string n)=>Type.GetType("LighthouseKeepers.WatchDemo."+n+", Assembly-CSharp",true);
  static object Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n).Invoke(o,a);
  static V Get<V>(object o,string n)=>(V)o.GetType().GetProperty(n).GetValue(o);
  static object New(int day=3){var cat=Resources.Load("M3Campaign");return Activator.CreateInstance(T("WatchState"),cat.GetType().GetField("nights").GetValue(cat),day,Resources.Load<S4Tuning>("S4Tuning"),Resources.Load<S4M2Tuning>("S4M2Tuning"),Resources.Load<ImmersionTuning>("ImmersionTuning"));}
  static int[] Code(object s){var r=Get<object>(s,"Radio");return Enumerable.Range(0,Get<int>(r,"CodeLength")).Select(i=>(int)Call(r,"CodeSymbol",i)).ToArray();}
  static void Ready(object s){Call(s,"CompleteRepair");Call(Get<object>(s,"Engine"),"Reset",.8f,0f,true);Call(s,"Tick",.1d);Call(s,"SetCircuit",0,false);Call(s,"SetCircuit",3,false);Call(s,"SetCircuit",1,true);Call(s,"SetCircuit",2,true);Call(s,"ResetBreaker");Call(s,"IgniteBeacon",true);Call(s,"AlignBeacon",Get<float>(Get<object>(s,"Beacon"),"Target"));Call(s,"WipeBeacon",1f);Call(s,"Tick",.1d);var r=Get<object>(s,"Radio");Call(r,"ToggleMain");var p=r.GetType().GetField("Program").GetValue(r);Call(r,"Tune",(float)p.GetType().GetField("targetMHz").GetValue(p));Call(s,"Tick",2d);Assert.AreEqual(2,Get<int>(r,"Step"));}
  [Test]public void RelayAssignsReaderAndOperatorWithoutGivingAwayAnswer(){var s=New();Call(s,"SetKeeperCount",2);Ready(s);var d=Get<object>(s,"Director");d.GetType().GetField("DutyForActor").SetValue(d,new Func<int,CrewDuty>(a=>a==1?CrewDuty.Machinist:CrewDuty.Lightkeeper));Call(d,"Tick",3f,1,Vector3.zero,2,Vector3.up*11,true);Assert.AreEqual("ReadCode",Get<object>(d,"First").ToString());Assert.AreEqual("RadioCode",Get<object>(d,"Second").ToString());var instruction=(string)Call(d,"Instruction",Get<object>(d,"Second"));foreach(string c in new[]{"RED","AMBER","BLUE","GREEN"})StringAssert.DoesNotContain(c,instruction.ToUpperInvariant());Assert.AreEqual(0,d.GetType().GetMethod("Floor").Invoke(null,new[]{Get<object>(d,"First")}));}
  [Test]public void CodeVariesByNightButIsStableOnRetryAndReplica(){var a=New(3);var b=New(4);CollectionAssert.AreNotEqual(Code(a),Code(b));var expected=Code(b);Call(b,"SetKeeperCount",2);Call(b,"Retry");CollectionAssert.AreEqual(expected,Code(b));var g=New(1);Call(g,"SetRemoteReplica",true);Assert.True((bool)Call(g,"ApplyRemote",Call(b,"Capture",.1f)));CollectionAssert.AreEqual(expected,Code(g));Assert.True(Get<bool>(g,"RadioRelay"));Call(g,"SetKeeperCount",1);Assert.True(Get<bool>(g,"RadioRelay"));}
  [Test]public void ClueAndButtonsAgreeAndMistakeKeepsTuning(){var s=New(5);Ready(s);var r=Get<object>(s,"Radio");var code=Code(s);Assert.AreEqual(1,Call(r,"PressCode",code[0]));Assert.AreEqual(0,Call(r,"PressCode",(code[1]+1)%4));Assert.True(Get<bool>(r,"Locked"));Assert.Zero(Get<int>(r,"CodeProgress"));string printed=(string)T("CodeSource").GetMethod("CodeText").Invoke(null,new[]{r});foreach(var symbol in code)StringAssert.Contains((symbol+1).ToString(),printed);foreach(int symbol in code)Assert.AreEqual(1,Call(r,"PressCode",symbol));Assert.True(Get<bool>(r,"CodeAccepted"));}
  [Test]public void LastHumanLeavingRestoresLocalCluePolicyAndPreservesCodeProgress(){var s=New();Call(s,"SetKeeperCount",2);Ready(s);var r=Get<object>(s,"Radio");Call(r,"PressCode",Code(s)[0]);Call(s,"SetKeeperCount",1);Assert.False(Get<bool>(s,"RadioRelay"));Assert.AreEqual(1,Get<int>(r,"CodeProgress"));}
 }
}
